-- Lot 204 : payloads 91 a 120 sur 150.
--
-- Un texte propre a chaque IA. Les commandes etant neuves, aucune version
-- courante n'existe : rien n'est retire, tout est pose.

drop table if exists lot_v5_1_payloads;
create temporary table lot_v5_1_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-361","moteur":"chatgpt","payload":"[RaccourcIA — /friendgroupcast]\n\nMISSION\nTransformez un groupe d’amis en distribution d’une série fictive avec rôles visuels. Créer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quel genre de série doit inspirer le groupe ? Puis, uniquement si encore nécessaire : Faut-il attribuer des rôles précis ou les déduire uniquement des poses visibles ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 16:9; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nChaque visage, carnation, position relative et taille du groupe.\n\nÉVITER ET RESPONSABILITÉ\nPersonne oubliée, rôle humiliant, personnalité inventée, visage fusionné, œuvre copiée et texte faux. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 16:9, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"4b09bc5656c4155ea747b2a7e0a4b23298f5cc5f02321821ab1988b0f043f10e"},{"ref":"RCI-IMG-361","moteur":"claude","payload":"[RaccourcIA — /friendgroupcast]\n\nMISSION\nTransformez un groupe d’amis en distribution d’une série fictive avec rôles visuels. Créer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, consolide-les sans longue reformulation et vérifie les capacités réellement disponibles avant de produire. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quel genre de série doit inspirer le groupe ? Puis, uniquement si encore nécessaire : Faut-il attribuer des rôles précis ou les déduire uniquement des poses visibles ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 16:9; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nChaque visage, carnation, position relative et taille du groupe.\n\nÉVITER ET RESPONSABILITÉ\nPersonne oubliée, rôle humiliant, personnalité inventée, visage fusionné, œuvre copiée et texte faux. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 16:9, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"cb2cd80f8f591e14cf7ea0817b699cd5624c4de23800eb6119016bc7e42b8735"},{"ref":"RCI-IMG-361","moteur":"gemini","payload":"[RaccourcIA — /friendgroupcast]\n\nMISSION\nTransformez un groupe d’amis en distribution d’une série fictive avec rôles visuels. Créer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte et relie chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quel genre de série doit inspirer le groupe ? Puis, uniquement si encore nécessaire : Faut-il attribuer des rôles précis ou les déduire uniquement des poses visibles ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 2 questions sur toute l’exécution.\n\nEXÉCUTION\nCréer une scène d’ensemble équilibrée, originale et narrative sans attribuer de traits personnels sensibles. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 16:9; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nChaque visage, carnation, position relative et taille du groupe.\n\nÉVITER ET RESPONSABILITÉ\nPersonne oubliée, rôle humiliant, personnalité inventée, visage fusionné, œuvre copiée et texte faux. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 16:9, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"b5d8d0033b28eb05faa962caed30b0760c8afd975e45de40544c5751cd9e9edd"},{"ref":"RCI-IMG-362","moteur":"chatgpt","payload":"[RaccourcIA — /clonecrew]\n\nMISSION\nMultipliez la personne dans une scène où chaque clone accomplit une action différente. Composer 3 à 6 clones avec interactions, profondeur, ombres et identités parfaitement cohérentes.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Utilise directement l’outil d’image disponible avec les références exactes. Exécute immédiatement si le contexte suffit. Ne redemande rien de visible, fourni ou déductible avec fiabilité. Une préférence facultative ne bloque jamais la production. Si une décision indispensable reste inconnue, pose une seule question dans ce tour : Quelles actions les différentes versions doivent-elles accomplir ? Après chaque réponse, réanalyse et produis dès que le contexte suffit. Accepte « Choisis pour moi », décide professionnellement et continue. Maximum 1 question sur toute l’exécution.\n\nEXÉCUTION\nComposer 3 à 6 clones avec interactions, profondeur, ombres et identités parfaitement cohérentes. Valeurs par défaut : Choix créatifs secondaires décidés automatiquement; ratio 16:9; haute définition; rendu partageable; aucun texte sauf s’il est utile et validé. Si du texte est nécessaire, utilise le texte exact fourni. Sinon choisis un mode sans texte.\n\nPRÉSERVER\nIdentité, carnation, silhouette, décor et logique spatiale.\n\nÉVITER ET RESPONSABILITÉ\nMembres fusionnés, répétition plate, actions dangereuses, visage instable et objets incohérents. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique, logo, identité ou événement. N’imite pas une personne publique, une marque, une franchise ou le style distinctif d’un artiste vivant. N’ajoute jamais « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Format par défaut : 16:9, haute définition. Avant de livrer, vérifie silencieusement identité ou forme du sujet, proportions, anatomie, perspective, lumière, ombres, matières, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"650a352aff4412c10018d662f52ebdb47dc0446c78a490245b173fdc2a1f07a2"},{"ref":"RCI-IMG-362","moteur":"cla